/**
 * 全量官方机制关键字 —— 【自动生成,请勿手改】
 *
 * 数据源:游戏本体 <root>/documentation/*.md(Paradox 随游戏发布的官方手册)。
 * 由 gen_official_docs.ts 抽取,重新生成:
 *   node gen_official_docs.ts
 *
 * 与手写 official-docs.ts 的关系:
 *   本文件是【全量数据】,由官方手册逐条解析而来,带作用域标注;
 *   official-docs.ts 保留少量手写条目作为兜底(手册缺项时的补充)。
 *
 * 各手册解析出的原始条目数:
 *   Modifiers                    1118
 *   Triggers                     646
 *   Effects                      602
 *   Console Commands             432
 *   Dynamic Variables            388
 *   Script Math Functions        30
 *   Localization Objects         15
 *   Localization Formatters      8
 *   Script Collection Input      6
 *   Script Concepts              6
 *   Script Collection Operator   5
 */

export type GenOfficialType =
  | 'effect'
  | 'trigger'
  | 'scope'
  | 'modifier'
  | 'other'

export interface GenOfficialEntry {
  name: string
  type: GenOfficialType
  /** 官方声明的适用作用域;空数组表示手册未标注 */
  scopes: string[]
  summary: string
  /** 出处手册名(同名条目可能多本) */
  books: string[]
}

